package app

// Settings holds server settings.
type Settings struct {
	Port int
	Name string
}

// Default returns the default Settings.
func Default() Settings {
	return Settings{Port: 8080, Name: "app"}
}

package app

// Describe returns a one-line description of a Settings.
func Describe(c Settings) string {
	return c.Name
}

package app

import "fmt"

// Server serves requests.
type Server struct {
	cfg Settings
}

// NewServer builds a Server from a Settings.
func NewServer(c Settings) *Server {
	return &Server{cfg: c}
}

func (s *Server) Addr() string {
	return fmt.Sprintf(":%d", s.cfg.Port)
}

package app

import "testing"

func TestBoot(t *testing.T) {
	if got := Boot(); got != ":8080 app" {
		t.Fatalf("Boot() = %q, want \":8080 app\"", got)
	}
	var c Settings = Default()
	if c.Port != 8080 {
		t.Fatalf("Port = %d", c.Port)
	}
}
